from pathlib import Path
import sys

Import("env")

scripts_dir = Path(env["PROJECT_DIR"]) / "scripts"
sys.path.insert(0, str(scripts_dir))

from versioning import build_version_string

project_dir = Path(env["PROJECT_DIR"])
version = build_version_string(project_dir)
generated = project_dir / "include" / "version_generated.h"
new_text = (
    '#pragma once\n'
    '// Generated by scripts/build_version.py; do not edit.\n'
    f'#define APP_VERSION "{version}"\n'
)
if not generated.exists() or generated.read_text(encoding="utf-8") != new_text:
    generated.write_text(new_text, encoding="utf-8")
print(f"Using APP_VERSION={version}")
